<?php require "db.php";$pageTitle="Drivers";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["name"]??"");$p=trim($_POST["phone"]??"");$l=trim($_POST["license_number"]??"");if($n&&$p&&$l){$s=$conn->prepare("INSERT INTO drivers(name,phone,license_number) VALUES(?,?,?)");$s->bind_param("sss",$n,$p,$l);$msg=$s->execute()?"Driver added successfully.":"Could not add driver; licence may already exist.";}else $msg="Complete all fields.";} $list=$conn->query("SELECT * FROM drivers ORDER BY id DESC");include "includes/header.php";?><div class="page-head"><div><p class="eyebrow">PEOPLE & ASSIGNMENTS</p><h1>Drivers</h1><p>Maintain driver contact and licence details.</p></div></div><?php if($msg):?><p class="notice"><?=htmlspecialchars($msg)?></p><?php endif;?><section class="panel"><h2>Add driver</h2><form method="post" class="form-grid"><label>Full name<input name="name" required></label><label>Phone<input name="phone" required></label><label>License number<input name="license_number" required></label><button class="button">Add driver</button></form></section><section class="panel"><h2>Driver directory</h2><?php if($list&&$list->num_rows):?><div class="table-wrap"><table><tr><th>Name</th><th>Phone</th><th>License</th><th>Status</th></tr><?php while($x=$list->fetch_assoc()):?><tr><td><?=htmlspecialchars($x["name"])?></td><td><?=htmlspecialchars($x["phone"])?></td><td><?=htmlspecialchars($x["license_number"])?></td><td><span class="badge"><?=htmlspecialchars($x["status"])?></span></td></tr><?php endwhile;?></table></div><?php else:?><p class="muted">No drivers registered yet.</p><?php endif;?></section><?php include "includes/footer.php";?>